using System;
using System.Data;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
namespace Videira { partial class MainForm {
 void ExpenseHub(){page="Despesas";Header("Financeiro • Central de despesas");var tabs=new TabControl{Dock=DockStyle.Fill};content.Controls.Add(tabs);tabs.BringToFront();foreach(bool plan in new[]{false,true}){string table=plan?"Plano mensal":"Despesas";var tab=new TabPage(plan?"Gastos mensais recorrentes / preço":"Todos os gastos lançados"){BackColor=Theme.Surface,Padding=new Padding(12)};tabs.TabPages.Add(tab);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,65));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,55));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,58));tab.Controls.Add(layout);var info=new Label{Dock=DockStyle.Fill,ForeColor=Color.DimGray,Text=plan?"Planejamento mensal usado na formação do preço. Clique em Gerar mês para criar os lançamentos financeiros.\nCada gasto é lançado uma única vez por mês; o dia do mês determina sua data.":"Todos os lançamentos aparecem aqui. A data define em qual período o gasto entra no resumo financeiro.\nDatas futuras aparecem no indicador Lançamentos futuros. Clique duas vezes para corrigir um lançamento."};layout.Controls.Add(info,0,0);var bar=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};layout.Controls.Add(bar,0,1);var filter=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=180};filter.Items.AddRange(new[]{"Todas as categorias","Gastos fixos","Gastos variáveis"});filter.SelectedIndex=0;bar.Controls.Add(filter);var find=new TextBox{Width=280};bar.Controls.Add(find);var summary=new Label{AutoSize=true,Margin=new Padding(16,8,0,0)};bar.Controls.Add(summary);var g=Theme.Grid();g.BindingContext=new BindingContext();g.Dock=DockStyle.Fill;layout.Controls.Add(g,0,2);Action refresh=()=>{var t=db.Data.Tables[table].Clone();foreach(DataRow r in db.Data.Tables[table].Rows)if((filter.SelectedIndex==0||r["Categoria"].ToString()==filter.Text)&&r["Descrição"].ToString().IndexOf(find.Text,StringComparison.CurrentCultureIgnoreCase)>=0)t.ImportRow(r);if(!plan){t.Columns.Add("No resumo",typeof(string));foreach(DataRow r in t.Rows)r["No resumo"]=(DateTime)r["Data"]>DateTime.Today?"Futuro: "+((DateTime)r["Data"]).ToString("MM/yyyy"):"Período: "+((DateTime)r["Data"]).ToString("MM/yyyy");}g.DataSource=t;g.Columns["Id"].Visible=false;if(g.Columns.Contains("Plano mensal"))g.Columns["Plano mensal"].Visible=false;g.Columns["Descrição"].FillWeight=280;g.Columns["Valor"].DefaultCellStyle.Format="N2";g.Columns["Valor"].DefaultCellStyle.Alignment=DataGridViewContentAlignment.MiddleRight;if(g.Columns.Contains("Data"))g.Columns["Data"].DefaultCellStyle.Format="dd/MM/yyyy";summary.Text=t.Rows.Count+" registro(s)  |  Total: R$ "+t.AsEnumerable().Sum(r=>(decimal)r["Valor"]).ToString("N2");};Func<DataRow> selected=()=>{if(g.CurrentRow==null)throw new Exception("Selecione um gasto.");var v=g.CurrentRow.DataBoundItem as DataRowView;if(v==null)throw new Exception("Selecione um gasto.");return db.Data.Tables[table].Rows.Find(v["Id"]);};filter.SelectedIndexChanged+=(s,e)=>refresh();find.TextChanged+=(s,e)=>refresh();g.CellDoubleClick+=(s,e)=>{if(e.RowIndex>=0)Run(()=>ExpenseEditor(table,selected(),refresh));};var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,Padding=new Padding(0,6,0,0)};layout.Controls.Add(actions,0,3);var newExpense=Btn("Novo gasto",()=>ExpenseEditor(table,null,refresh));newExpense.Width=140;actions.Controls.Add(newExpense);actions.Controls.Add(Btn("Editar",()=>ExpenseEditor(table,selected(),refresh)));actions.Controls.Add(Btn("Excluir",()=>{var r=selected();if(MessageBox.Show("Excluir este lançamento?","Despesas",MessageBoxButtons.YesNo)==DialogResult.Yes){db.Atomic(()=>db.Data.Tables[table].Rows.Remove(r));refresh();}}));if(plan){var month=new DateTimePicker{Format=DateTimePickerFormat.Custom,CustomFormat="MM/yyyy",ShowUpDown=true,Width=100};actions.Controls.Add(month);var generate=Btn("Gerar mês",()=>{if(MessageBox.Show("Gerar os gastos planejados de "+month.Value.ToString("MM/yyyy")+"?\nOs registros já gerados neste mês serão preservados.","Lançamentos mensais",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;int count=db.GenerateMonth(month.Value);MessageBox.Show(count+" lançamento(s) criado(s). Consulte a aba Todos os gastos lançados e o resumo do mesmo período.","Despesas");tabs.SelectedIndex=0;ExpenseHub();});generate.Width=145;actions.Controls.Add(generate);}var finance=Btn("Resumo financeiro",FinancePage);finance.Width=200;actions.Controls.Add(finance);var export=Btn("Exportar CSV",()=>{grid=g;Export();});export.Width=155;actions.Controls.Add(export);actions.Controls.Add(Btn("Sair",Home));refresh();}AddMaterialsTab(tabs);}
 void ExpenseEditor(string table,DataRow row,Action refresh){bool plan=table=="Plano mensal";using(var d=new Dialog(plan?"Gasto recorrente / planejamento de preço":"Lançar ou editar gasto financeiro",790,570)){var category=d.Choice("Categoria",new[]{"Gastos fixos","Gastos variáveis"});if(row!=null)category.SelectedItem=row["Categoria"].ToString();if(row!=null&&!plan&&(int)row["Insumo"]>0)category.Enabled=false;DateTimePicker date=null;NumericUpDown day=null;if(!plan){date=new DateTimePicker{Format=DateTimePickerFormat.Short,Value=row==null?DateTime.Today:(DateTime)row["Data"]};d.Add("Data do gasto",date);}else day=d.Number("Dia do mês",row==null?1:(int)row["Dia do mês"],31,0);var description=d.TextField("Descrição",row==null?"":row["Descrição"].ToString());var amount=d.Number("Valor (R$)",row==null?0:(decimal)row["Valor"]);var recurring=new CheckBox{Text="Usar também no planejamento mensal do preço",AutoSize=true};if(!plan)d.Add("Recorrência",recurring);if(row!=null&&!plan&&(int)row["Insumo"]>0)recurring.Enabled=false;var note=new Label{AutoSize=true,MaximumSize=new Size(550,100),ForeColor=Color.DimGray};d.Add("No financeiro",note);Action updateNote=()=>{note.Text=plan?"O planejamento só entra no resultado quando você gerar os lançamentos do mês.":date.Value.Date>DateTime.Today?"Lançamento futuro. Aparecerá no resumo de "+date.Value.ToString("MM/yyyy")+" e no indicador Lançamentos futuros.":"Este gasto entrará no resumo financeiro do período que inclui "+date.Value.ToString("dd/MM/yyyy")+".";};if(date!=null)date.ValueChanged+=(s,e)=>updateNote();updateNote();d.Commit(()=>{if(string.IsNullOrWhiteSpace(description.Text)||amount.Value<=0||(plan&&day.Value<1))throw new Exception("Informe descrição, valor positivo e dia válido.");db.Atomic(()=>{var r=row??db.Data.Tables[table].NewRow();if(row==null)r["Id"]=db.Next(table);r["Categoria"]=category.Text;r["Descrição"]=description.Text.Trim();r["Valor"]=amount.Value;if(date!=null)r["Data"]=date.Value.Date;if(plan)r["Dia do mês"]=(int)day.Value;if(row==null)db.Data.Tables[table].Rows.Add(r);if(!plan&&recurring.Checked){var p=db.Data.Tables["Plano mensal"].AsEnumerable().FirstOrDefault(x=>x["Descrição"].ToString().Equals(description.Text.Trim(),StringComparison.CurrentCultureIgnoreCase)&&x["Categoria"].ToString()==category.Text);if(p==null){p=db.Data.Tables["Plano mensal"].NewRow();p["Id"]=db.Next("Plano mensal");p["Descrição"]=description.Text.Trim();p["Categoria"]=category.Text;db.Data.Tables["Plano mensal"].Rows.Add(p);}p["Valor"]=amount.Value;p["Dia do mês"]=date.Value.Day;r["Plano mensal"]=p["Id"];}});});if(preview&&activePreviewMode=="--preview-expense-flow"&&!plan)d.Shown+=(s,e)=>{description.Text="TESTE UI INTEGRAÇÃO";amount.Value=123m;date.Value=DateTime.Today;category.SelectedIndex=0;((Button)d.AcceptButton).PerformClick();};if(d.ShowDialog(this)==DialogResult.OK){refresh();if(preview&&activePreviewMode=="--preview-expense-flow"){var f=db.Finance(DateTime.Today,DateTime.Today);if((decimal)f.Rows[6][1]<123m)throw new Exception("Lançamento da UI não integrado.");System.IO.File.WriteAllText(System.IO.Path.Combine(Environment.CurrentDirectory,"work","expense-ui-result.txt"),"PASS: lançamento salvo pelo formulário aparece no resumo financeiro do período.");}}}}
}}

